package com.example.doctoolkit;
import android.app.*; import android.content.*; import android.net.Uri; import android.os.*; import android.provider.OpenableColumns; import android.database.Cursor; import android.view.*; import android.widget.*; import java.util.*; import com.example.doctoolkit.ui.*;
public class MainActivity extends Activity { private String selectedTool="convert"; private final ActivityResultLauncherCompat picker=new ActivityResultLauncherCompat(this); public void onCreate(Bundle b){super.onCreate(b); setContentView(com.example.doctoolkit.R.layout.activity_main); GridLayout grid=findViewById(R.id.toolGrid); for(String tool: Arrays.asList("Convert","Compress","Merge","Split","OCR")){ Button btn=new Button(this); btn.setText(tool); btn.setOnClickListener(v->{selectedTool=tool.toLowerCase(Locale.US); picker.open("application/pdf,image/*,application/vnd.openxmlformats-officedocument.wordprocessingml.document");}); grid.addView(btn,new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,160)); } findViewById(R.id.historyButton).setOnClickListener(v->startActivity(new Intent(this, HistoryActivity.class))); }
 public void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d); if(r==42&&c==RESULT_OK&&d!=null){Uri u=d.getData(); Intent i=new Intent(this, UploadActivity.class); i.setData(u); i.putExtra("tool",selectedTool); i.putExtra("name",displayName(u)); startActivity(i);}} private String displayName(Uri u){try(Cursor cur=getContentResolver().query(u,null,null,null,null)){if(cur!=null&&cur.moveToFirst()){int idx=cur.getColumnIndex(OpenableColumns.DISPLAY_NAME); if(idx>=0)return cur.getString(idx);}} return "input";} static class ActivityResultLauncherCompat{private final Activity a; ActivityResultLauncherCompat(Activity a){this.a=a;} void open(String types){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT); i.addCategory(Intent.CATEGORY_OPENABLE); i.setType("*/*"); i.putExtra(Intent.EXTRA_MIME_TYPES, types.split(",")); a.startActivityForResult(i,42);}} }
